"""flash_attn.bert_padding — iOS shim (pure torch).

The pad/unpad helpers transformers imports next to flash_attn_func.
Reference semantics from flash-attn 2.x; returns the 4-tuple layout
transformers 4.41.x expects from unpad_input.
"""
import torch
import torch.nn.functional as F

__all__ = ["index_first_axis", "pad_input", "unpad_input"]


def index_first_axis(x, indices):
    """Gather rows of x (first axis) at `indices`. Autograd-safe."""
    return x[indices]


def pad_input(hidden_states, indices, batch, seqlen):
    """Inverse of unpad_input: scatter (total, ...) rows back into
    (batch, seqlen, ...) with zeros at padding positions."""
    out = torch.zeros(batch * seqlen, *hidden_states.shape[1:],
                      dtype=hidden_states.dtype, device=hidden_states.device)
    out[indices] = hidden_states
    return out.view(batch, seqlen, *hidden_states.shape[1:])


def unpad_input(hidden_states, attention_mask, unused_mask=None):
    """Drop padding tokens.

    hidden_states: (batch, seqlen, ...); attention_mask: (batch, seqlen)
    with 1 = real token, 0 = padding.
    Returns (unpadded (total, ...), indices, cu_seqlens int32, max_seqlen).
    """
    seqlens = attention_mask.sum(dim=-1, dtype=torch.int32)
    indices = torch.nonzero(attention_mask.flatten(), as_tuple=False).flatten()
    max_seqlen = int(seqlens.max())
    cu_seqlens = F.pad(torch.cumsum(seqlens, dim=0, dtype=torch.int32), (1, 0))
    flat = hidden_states.reshape(-1, *hidden_states.shape[2:])
    return flat[indices], indices, cu_seqlens, max_seqlen
